/* ─────────────────────── shared helpers ─────────────────────── */

async function ensureRwaAssetClassId(tx: any = db): Promise<string> {
  let [klass] = await tx.select().from(assetClasses).where(eq(assetClasses.code, "RWA")).limit(1);
  if (!klass) {
    [klass] = await tx
      .insert(assetClasses)
      .values({ code: "RWA", name: "دارایی واقعی", color: "#12131c", sortOrder: 90 })
      .onConflictDoNothing()
      .returning();
    if (!klass) [klass] = await tx.select().from(assetClasses).where(eq(assetClasses.code, "RWA")).limit(1);
  }
  if (!klass) throw new Error("کلاس دارایی واقعی ایجاد نشد.");
  return klass.id;
}

/** The ledger's base currency asset (equity leg of opening entries uses it). */
async function ensureUsdAssetId(tx: any = db): Promise<string> {
  let [usdAsset] = await tx.select().from(assets).where(eq(assets.symbol, "USD")).limit(1);
  if (!usdAsset) {
    const classId = await ensureRwaAssetClassId(tx);
    [usdAsset] = await tx
      .insert(assets)
      .values({ symbol: "USD", name: "دلار آمریکا", classId, decimals: 2, priceSource: "manual" })
      .onConflictDoNothing()
      .returning();
    if (!usdAsset) [usdAsset] = await tx.select().from(assets).where(eq(assets.symbol, "USD")).limit(1);
  }
  if (!usdAsset) throw new Error("دارایی پایه (USD) یافت نشد.");
  return usdAsset.id;
}

/**
 * Real Estate ledger accounts (global, consistent with the seeded chart of
 * accounts — 1xxx assets / 3xxx equity):
 *   1600  املاک و مستغلات                 (asset)
 *   3015  سرمایه افتتاحیه تملک‌های تاریخی (equity)
 */
async function ensureRealEstateLedgerAccounts(tx: any = db): Promise<{ assetAccountId: string; openingEquityAccountId: string }> {
  const getByCode = async (code: string) => {
    // Global chart-of-accounts rows (user_id NULL) — consistent with the seed.
    const [row] = await tx.select().from(accounts).where(and(eq(accounts.code, code), isNull(accounts.userId))).limit(1);
    return row ?? null;
  };

  let assetAccount = await getByCode("1600");
  if (!assetAccount) {
    [assetAccount] = await tx
      .insert(accounts)
      .values({ code: "1600", name: "املاک و مستغلات", type: "asset" })
      .onConflictDoNothing({ target: [accounts.userId, accounts.code] })
      .returning();
    if (!assetAccount) assetAccount = await getByCode("1600");
  }

  let equityAccount = await getByCode("3015");
  if (!equityAccount) {
    [equityAccount] = await tx
      .insert(accounts)
      .values({ code: "3015", name: "سرمایه افتتاحیه تملک‌های تاریخی (املاک)", type: "equity" })
      .onConflictDoNothing({ target: [accounts.userId, accounts.code] })
      .returning();
    if (!equityAccount) equityAccount = await getByCode("3015");
  }

  if (!assetAccount || !equityAccount) throw new Error("حساب‌های دفترکل املاک ایجاد نشدند.");
  return { assetAccountId: assetAccount.id, openingEquityAccountId: equityAccount.id };
}

/* ─────────────────────── name & symbol generation ─────────────────────── */

/**
 * Number of already-registered properties with the same
 * (city, neighborhood, property type) — drives the human-readable name suffix.
 * The compact symbol uses the separate global RWA sequence.
 */
async function nextPropertySequence(cityId: string, neighborhoodId: string, propertyTypeId: string): Promise<number> {
  const [row] = await db
    .select({ c: sql<number>`count(*)::int` })
    .from(realEstateProperties)
    .where(
      and(
        eq(realEstateProperties.cityId, cityId),
        eq(realEstateProperties.neighborhoodId, neighborhoodId),
        eq(realEstateProperties.propertyTypeId, propertyTypeId),
      ),
    );
  return (Number(row?.c ?? 0) || 0) + 1;
}

/** Short numeric identifier for properties (`001`, `002`, …). */
export function buildAssetName(p: PropertyType, city: City, hood: Neighborhood, sequence: number, symbol?: string): string {
  return symbol ?? buildRwaSymbol(sequence);
}

/** Compact canonical RWA id (`001`, `002`, …). Shared with vehicles. */
export function buildSymbol(sequence: number): string {
  return buildRwaSymbol(sequence);
}

/** Live preview of the generated name/symbol (used by the registration form). */
export async function previewRealEstateIdentity(
  cityId: string,
  neighborhoodId: string,
  propertyTypeId: string,
): Promise<RealEstateNamePreview | null> {
  const [city, hood, ptype] = await Promise.all([getCity(cityId), getNeighborhood(neighborhoodId), getPropertyType(propertyTypeId)]);
  if (!city || !hood || !ptype) return null;
  const sequence = await nextPropertySequence(cityId, neighborhoodId, propertyTypeId);
  const symbol = await nextRwaSymbol();
  return {
    assetName: symbol,
    // Preview is advisory; the final transaction resolves and locks again.
    symbol,
    sequence,
  };
}

/* ─────────────────────── performance (derived, never stored) ─────────────────────── */

export function computePerformance(
  purchaseToman: string | null,
  currentToman: string | null,
  purchaseUsd: string | null,
  currentUsd: string | null,
): RealEstatePerformance {
  if (!purchaseToman || !currentToman) {
    return { gainToman: null, roiToman: null, gainUsd: null, roiUsd: null };
  }
  const pT = D(purchaseToman);
  const cT = D(currentToman);
  const gainToman = cT.sub(pT);
  const roiToman = pT.gt(0) ? gainToman.div(pT).mul("100").toFixed(2) : null;
  let gainUsd: string | null = null;
  let roiUsd: string | null = null;
  if (purchaseUsd && currentUsd && D(purchaseUsd).gt(0)) {
    const pU = D(purchaseUsd);
    const cU = D(currentUsd);
    gainUsd = cU.sub(pU).toFixed(2);
    roiUsd = pU.gt(0) ? cU.sub(pU).div(pU).mul("100").toFixed(2) : null;
  }
  return { gainToman: gainToman.toFixed(0), roiToman, gainUsd, roiUsd };
}

/* ─────────────────────── valuation snapshots (immutable history) ─────────────────────── */

const num = (v: unknown): string | null => (v === null || v === undefined ? null : D(v as string).toString());
const tomanStr = (v: unknown): string | null => (v === null || v === undefined ? null : D(v as string).toFixed(0));
const usdStr = (v: unknown): string | null => (v === null || v === undefined ? null : D(v as string).toFixed(2));

function mapSnapshot(row: typeof realEstateValuationSnapshots.$inferSelect): RealEstateValuationSnapshot {
  return {
    id: row.id,
    propertyId: row.propertyId,
    assetId: row.assetId,
    userId: row.userId ?? null,
    snapshotDate: row.snapshotDate,
    snapshotDatePersian: row.snapshotDatePersian ?? null,
    currentValueToman: tomanStr(row.currentValueToman) ?? "0",
    usdRate: num(row.usdRate) ?? "0",
    usdRateSource: row.usdRateSource ?? null,
    usdRateDate: row.usdRateDate ?? null,
    currentValueUsd: usdStr(row.currentValueUsd) ?? "0",
    source: row.source,
    note: row.note ?? null,
    createdAt: row.createdAt?.toISOString() ?? new Date().toISOString(),
  };
}

/**
 * INSERT a new immutable valuation snapshot inside a transaction. Existing
 * snapshots are never updated: a second valuation for the same day is
 * refused — a new value must be recorded on a new date (same rule as the
 * vehicle module). This is what makes "ارزش سه ماه پیش" undeletable.
 */
async function insertValuationSnapshot(
  tx: any,
  input: {
    propertyId: string;
    assetId: string;
    userId?: string | null;
    snapshotDate: string;
    snapshotDatePersian?: string | null;
    currentValueToman: string;
    usdRate: string;
    usdRateSource?: string | null;
    usdRateDate?: string | null;
    currentValueUsd: string;
    source?: string;
    note?: string | null;
  },
): Promise<string> {
  const [existing] = await tx
    .select({ id: realEstateValuationSnapshots.id })
    .from(realEstateValuationSnapshots)
    .where(
      and(
        eq(realEstateValuationSnapshots.propertyId, input.propertyId),
        eq(realEstateValuationSnapshots.snapshotDate, input.snapshotDate),
      ),
    )
    .limit(1);
  if (existing) {
    throw new Error(
      "برای این تاریخ ارزش‌گذاری ثبت شده است. اسنپ‌شات‌های قبلی تغییرناپذیرند؛ برای ارزش جدید یک تاریخ جدید ثبت کنید.",
    );
  }
  const [row] = await tx
    .insert(realEstateValuationSnapshots)
    .values({
      propertyId: input.propertyId,
      assetId: input.assetId,
      userId: input.userId ?? null,
      snapshotDate: input.snapshotDate,
      snapshotDatePersian: input.snapshotDatePersian ?? null,
      currentValueToman: D(input.currentValueToman).toFixed(0),
      usdRate: D(input.usdRate).toString(),
      usdRateSource: input.usdRateSource ?? "manual",
      usdRateDate: input.usdRateDate ?? input.snapshotDate,
      currentValueUsd: input.currentValueUsd,
      source: input.source ?? "manual",
      note: input.note ?? null,
    })
    .returning({ id: realEstateValuationSnapshots.id });
  return row.id;
}

/** All valuation snapshots of one property, oldest first (immutable history). */
export async function listRealEstateValuationSnapshots(
  propertyId: string,
  userId?: string | null,
): Promise<RealEstateValuationSnapshot[]> {
  const rows = await db
    .select()
    .from(realEstateValuationSnapshots)
    .where(
      and(
        eq(realEstateValuationSnapshots.propertyId, propertyId),
        userId ? eq(realEstateValuationSnapshots.userId, userId) : undefined,
      ),
    )
    .orderBy(asc(realEstateValuationSnapshots.snapshotDate));
  return rows.map(mapSnapshot);
}

/**
 * Snapshots of a tenant's whole portfolio, grouped by property. Scoped at the
 * DB query level (NULL-owned rows are NOT shared with identified tenants).
 */
async function loadSnapshotsByProperty(userId?: string | null): Promise<Map<string, RealEstateValuationSnapshot[]>> {
  const rows = await db
    .select()
    .from(realEstateValuationSnapshots)
    .where(userId ? eq(realEstateValuationSnapshots.userId, userId) : undefined)
    .orderBy(asc(realEstateValuationSnapshots.snapshotDate));
  const map = new Map<string, RealEstateValuationSnapshot[]>();
  for (const row of rows) {
    const list = map.get(row.propertyId) ?? [];
    list.push(mapSnapshot(row));
    map.set(row.propertyId, list);
  }
  return map;
}

